REMEDIATION_CODE_TERRAFORM:
```hcl
# Terraform: enable Bedrock data event logging on an actively logging trail
resource "aws_cloudtrail" "example_resource" {
  name           = "example_resource"
  s3_bucket_name = "example_resource"

  advanced_event_selector {
    name = "Bedrock data events"
    field_selector {
      field  = "eventCategory"
      equals = ["Data"]
    }
    field_selector {
      field  = "resources.type"                # CRITICAL: target Bedrock resources
      equals = ["AWS::Bedrock::Model", "AWS::Bedrock::Guardrail", "AWS::Bedrock::AgentAlias", "AWS::Bedrock::FlowAlias", "AWS::Bedrock::InlineAgent", "AWS::Bedrock::KnowledgeBase", "AWS::Bedrock::Prompt"]
    }
  }
}
```

```hcl
resource "aws_cloudtrail" "<example_resource_name>" {
  name           = "<example_resource_name>"
  s3_bucket_name = "<example_resource_name>"
  enable_logging = true

  insight_selector {
    insight_type = "ApiCallRateInsight"  # Critical fix: enables CloudTrail Insights on the trail
  }
}
```

```hcl
# Enable access logging on the CloudTrail S3 bucket
resource "aws_s3_bucket" "<example_log_bucket_name>" {
  bucket = "<example_log_bucket_name>"
}

resource "aws_s3_bucket" "<example_bucket_name>" {
  bucket = "<example_bucket_name>"
}

resource "aws_s3_bucket_logging" "<example_resource_name>" {
  bucket        = aws_s3_bucket.<example_bucket_name>.id
  target_bucket = aws_s3_bucket.<example_log_bucket_name>.id  # Critical: enables server access logging to the target bucket
}
```

```hcl
# Terraform: enable multi-region and log management events (read & write)
resource "aws_cloudtrail" "<example_resource_name>" {
  name           = "<example_resource_name>"
  s3_bucket_name = "<example_resource_name>"

  is_multi_region_trail = true  # CRITICAL: apply the trail to all regions

  event_selector {
    include_management_events = true  # CRITICAL: log management events
    read_write_type           = "All" # CRITICAL: log both read & write
  }
}
```

```hcl
# Terraform: enable S3 object-level READ data events for all buckets on a trail
resource "aws_cloudtrail" "<example_resource_name>" {
  name           = "<example_resource_name>"
  s3_bucket_name = "<example_resource_name>"

  event_selector {
    read_write_type = "ReadOnly"                 # CRITICAL: log read-only data events
    data_resource {
      type   = "AWS::S3::Object"                 # CRITICAL: target S3 object-level events
      values = ["arn:aws:s3"]                    # CRITICAL: apply to all S3 buckets/objects
    }
  }
}
```

```hcl
resource "aws_cloudtrail" "<example_resource_name>" {
  name           = "<example_resource_name>"
  s3_bucket_name = "<example_resource_name>"

  event_selector {
    read_write_type = "WriteOnly"
    data_resource {
      type   = "AWS::S3::Object"
      values = ["arn:aws:s3"]  # Critical: logs S3 object-level write events for all buckets to pass the check
    }
  }
}
```

```hcl
# Apply a CloudWatch Logs data protection policy to mask secrets
resource "aws_cloudwatch_log_group" "log_group" {
  name = "<example_resource_name>"

  # Critical: Masks detected credentials so secrets aren't visible and the check passes
  data_protection_policy = jsonencode({
    Statement = [
      {
        DataIdentifier = [
          "arn:aws:dataprotection::aws:data-identifier/Credentials"
        ]
        Operation = { Audit = { FindingsDestination = {} } }
      },
      {
        DataIdentifier = [
          "arn:aws:dataprotection::aws:data-identifier/Credentials"
        ]
        Operation = { Deidentify = { MaskConfig = {} } }
      }
    ]
  })
}
```

