```hcl
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name                 = "<example_resource_name>"
  deletion_protection  = "ACTIVE" # Critical: Enables deletion protection to prevent accidental pool deletion
}
```

```hcl
# Terraform: Require MFA and enable TOTP
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name              = "<example_resource_name>"
  mfa_configuration = "ON" # Critical: sets MFA to required

  software_token_mfa_configuration {
    enabled = true # Critical: enables TOTP so ON is valid
  }
}
```

```hcl
resource "aws_cognito_user_pool" "pool" {
  name = "<example_resource_name>"

  password_policy {
    require_lowercase = true  # Critical: enforces at least one lowercase character
  }
}
```

```hcl
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name = "<example_resource_name>"

  password_policy {
    minimum_length = 14  # Critical: enforce min length >=14 to pass the check
  }
}
```

```hcl
# Terraform: Enable number requirement in Cognito password policy
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name = "<example_resource_name>"

  password_policy {
    require_numbers = true  # Critical: enforces at least one numeric character in passwords
  }
}
```

```hcl
# Terraform: ensure Cognito User Pool requires at least one symbol in passwords
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name = "<example_resource_name>"

  password_policy {
    require_symbols = true  # Critical: enforce at least one symbol to pass the check
  }
}
```

```hcl
# Require uppercase in Cognito User Pool password policy
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name = "<example_resource_name>"

  password_policy {
    require_uppercase = true  # Critical: enforce at least one uppercase letter
  }
}
```

```hcl
# Terraform: Disable self-registration in a Cognito User Pool
resource "aws_cognito_user_pool" "<example_resource_name>" {
  admin_create_user_config {
    allow_admin_create_user_only = true  # Critical: disables self sign-up; only admins can create users
  }
}
```

```hcl
# Terraform: Set Cognito temporary password expiration to 7 days or less
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name = "<example_resource_name>"

  password_policy {
    temporary_password_validity_days = 7  # Critical: 7 or less to pass the check
  }
}
```

```hcl
resource "aws_ec2_image_block_public_access" "<example_resource_name>" {
  state = "block-new-sharing" # Blocks new public sharing of AMIs in the configured Region
}
```

```hcl
resource "aws_ebs_encryption_by_default" "<example_resource_name>" {
  enabled = true  # Critical: enables default EBS encryption in this region
}
```

```hcl
# Minimal AWS Backup plan protecting all EBS volumes
resource "aws_backup_plan" "<example_resource_name>" {
  name = "<example_resource_name>"

  rule {
    rule_name         = "<example_rule_name>"
    target_vault_name = "Default"
  }
}

resource "aws_backup_selection" "<example_resource_name>" {
  name         = "<example_resource_name>"
  plan_id      = aws_backup_plan.<example_resource_name>.id
  iam_role_arn = "arn:aws:iam::<example_account_id>:role/service-role/AWSBackupDefaultServiceRole"

  resources = [
    "arn:aws:ec2:*:*:volume/*" # Critical: selects all EBS volumes to satisfy the check
  ]
}
```

```hcl
# Create a snapshot for an existing EBS volume
resource "aws_ebs_snapshot" "<example_resource_name>" {
  volume_id = "<example_resource_id>" # Critical: creating this snapshot makes the volume pass the check
}
```

```hcl
# Enforce IMDSv2 on an EC2 instance
resource "aws_instance" "<example_resource_name>" {
  ami           = "<example_resource_id>"
  instance_type = "<example_resource_name>"

  metadata_options {
    http_tokens = "required"  # Critical: Require IMDSv2 tokens (blocks IMDSv1)
  }
}
```

```hcl
# Terraform: make the instance SSM-managed by attaching the required IAM role
resource "aws_iam_role" "<example_resource_name>" {
  name               = "<example_resource_name>"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action   = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "<example_resource_name>_ssm" {
  role       = aws_iam_role.<example_resource_name>.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"  # CRITICAL: grants SSM permissions required for management
}

resource "aws_iam_instance_profile" "<example_resource_name>" {
  name = "<example_resource_name>"
  role = aws_iam_role.<example_resource_name>.name
}

resource "aws_instance" "<example_resource_name>" {
  ami                  = "ami-<example_resource_id>"
  instance_type        = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.<example_resource_name>.name  # CRITICAL: attaches the SSM-enabled role to the instance
}
```

```hcl
# Security group with Cassandra ports not open to the Internet
resource "aws_security_group" "<example_resource_name>" {
  name   = "<example_resource_name>"
  vpc_id = "<example_resource_id>"

  # FIX: restrict these ports; do not use 0.0.0.0/0
  ingress { from_port = 7000 to_port = 7000 protocol = "tcp" cidr_blocks = ["10.0.0.0/8"] }
  ingress { from_port = 7001 to_port = 7001 protocol = "tcp" cidr_blocks = ["10.0.0.0/8"] }
  ingress { from_port = 7199 to_port = 7199 protocol = "tcp" cidr_blocks = ["10.0.0.0/8"] }
  ingress { from_port = 9042 to_port = 9042 protocol = "tcp" cidr_blocks = ["10.0.0.0/8"] }
  ingress { from_port = 9160 to_port = 9160 protocol = "tcp" cidr_blocks = ["10.0.0.0/8"] }
}
```

```hcl
# Security group without CIFS open to the Internet
resource "aws_security_group" "<example_resource_name>" {
  name   = "<example_resource_name>"
  vpc_id = "<example_resource_id>"

  ingress {
    from_port   = 139
    to_port     = 139
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"] # CRITICAL: restrict CIFS (139); do not use 0.0.0.0/0
  }

  ingress {
    from_port   = 445
    to_port     = 445
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"] # CRITICAL: restrict CIFS (445); do not use 0.0.0.0/0
  }
}
```

```hcl
# Terraform: restrict Elasticsearch/Kibana ports to a private CIDR (not the Internet)
resource "aws_security_group" "<example_resource_name>" {
  name   = "<example_resource_name>"
  vpc_id = "<example_resource_id>"

  # CRITICAL: restrict sources; do NOT use 0.0.0.0/0 or ::/0
  ingress {
    from_port   = 9200
    to_port     = 9200
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }
  ingress {
    from_port   = 9300
    to_port     = 9300
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }
  ingress {
    from_port   = 5601
    to_port     = 5601
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }
}
```

